/*
 * prog21_date_validator
 *
 * The original binary validates a date supplied as a single command‑line
 * argument.  The expected format is exactly ten characters:
 *
 *     YYYY-MM-DD
 *
 * where each character is an ASCII digit except the two hyphens at
 * positions 4 and 7.  The program checks that the string has the correct
 * length, that the hyphens are present, that all other characters are
 * digits, and finally that the year, month and day constitute a real
 * calendar date (including the Gregorian leap‑year rule).
 *
 * If the input satisfies all checks the program prints "VALID",
 * otherwise it prints "INVALID".  When no argument is supplied the
 * program also prints "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

static bool is_leap_year(int year)
{
    /* Gregorian leap‑year rule */
    return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}

static bool validate_date(const char *s)
{
    /* Expected format: YYYY-MM-DD (10 characters) */
    if (strlen(s) != 10)
        return false;

    if (s[4] != '-' || s[7] != '-')
        return false;

    /* All other characters must be digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (s[i] < '0' || s[i] > '9')
            return false;
    }

    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');
    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    if (month < 1 || month > 12)
        return false;
    if (day < 1)
        return false;

    static const int days_in_month[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    int max_day = days_in_month[month - 1];
    if (month == 2 && is_leap_year(year))
        max_day = 29;

    return day <= max_day;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
